.Links{
  display:grid;
  grid-template-columns:repeat(7, 160px);
  justify-content:center;
  gap:22px;
}
.Links>a{
  width:100px;
  height:50px;
  display:flex;
  align-items:center;
  justify-content:center;
  background:linear-gradient(145deg, rgba(30,30,46,0.6), rgba(30,30,46,0.4));
  backdrop-filter:blur(12px);
  -webkit-backdrop-filter:blur(12px);
  border-radius:16px;
  border:1px solid rgba(205,214,244,0.12);
  color:#cdd6f4;
  font-weight:600;
  font-size:0.9rem;
  letter-spacing:0.1px;
  box-shadow:
    0 2px 6px rgba(0,0,0,0.35),
    0 8px 20px rgba(0,0,0,0.2),
    inset 0 1px 0 rgba(255,255,255,0.08);
  overflow:hidden;
  white-space:nowrap;
  text-overflow:ellipsis;
  text-decoration:none;
  position:relative;
  transition:transform 0.25s cubic-bezier(.2,.8,.2,1), background 0.25s ease, box-shadow 0.25s ease;
}

/* traveling glow border */
.Links>a::before{
  content:"";
  position:absolute;
  inset:0;
  border-radius:inherit;
  padding:1.5px;
  background:linear-gradient(90deg, transparent, transparent);
  background-size:250% 100%;
  background-position:-100% 0;
  -webkit-mask:linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite:xor;
  mask-composite:exclude;
  pointer-events:none;
}
.Links>a:hover::before{
  background:linear-gradient(90deg, transparent, #cba6f7 45%, #f5e8ff 50%, #cba6f7 55%, transparent);
  background-size:250% 100%;
  animation:borderTravel 1.6s linear infinite;
}
@keyframes borderTravel{
  0%{background-position:-100% 0;}
  100%{background-position:100% 0;}
}

/* shine sweep */
.Links>a::after{
  content:"";
  position:absolute;
  top:0;
  left:-150%;
  width:60%;
  height:100%;
  background:linear-gradient(115deg, transparent, rgba(255,255,255,0.12), transparent);
  pointer-events:none;
}
.Links>a:hover::after{
  animation:shineSweep 0.9s ease forwards;
}
@keyframes shineSweep{
  to{left:150%;}
}

.Links>a:hover,
.Links>a:focus,
.Links>a:active,
.Links>a:visited{
  text-decoration:none;
}
.Links>a:hover{
  transform:translateY(-4px) scale(1.03);
  background:linear-gradient(145deg, rgba(203,166,247,0.22), rgba(203,166,247,0.1));
  box-shadow:
    0 10px 28px rgba(203,166,247,0.3),
    inset 0 1px 0 rgba(255,255,255,0.08);
}
.Links>a:active{
  transform:translateY(-1px) scale(0.98);
}
.Links>a span{
  color:#cdd6f4 !important;
  text-decoration:none !important;
}
